/* The page keeps one compact entry point; the existing planner is moved intact. */
(()=>{const section=document.querySelector('#routines'),dialog=document.createElement('dialog');dialog.id='routineSetupDialog';dialog.setAttribute('aria-labelledby','routineDialogTitle');dialog.innerHTML='<div class="dialog-heading"><div><p class="eyebrow">BUILD YOUR TRAINING WEEK</p><h2 id="routineDialogTitle">Your routine studio</h2></div><button type="button" class="close" aria-label="Close routine setup">×</button></div><p class="muted">Set your preferences, review the plan, then save it to your calendar.</p>';const content=document.createElement('div');content.className='routine-popup-content';while(section.firstChild)content.append(section.firstChild);dialog.append(content);const footer=document.createElement('div');footer.className='routine-popup-footer';footer.innerHTML='<button type="button" class="secondary">View my calendar →</button>';footer.querySelector('button').onclick=()=>{dialog.close();if(window.PagePanels)PagePanels.open('calendar');else document.querySelector('#calendar').scrollIntoView({behavior:'smooth'});};dialog.append(footer);document.body.append(dialog);
section.innerHTML='<div class="routine-launch"><div><p class="eyebrow">02 / YOUR TRAINING PLAN</p><h2 id="routineLaunchHeading">A stronger week starts here.</h2><p>Build a routine around your goal, equipment and schedule.</p><span id="routineSavedSummary"></span></div><button type="button" class="primary" id="openRoutineStudio">Set up my routine <span>→</span></button></div>';
function summary(){try{const record=JSON.parse(localStorage.getItem('form-fuel-routines-v1'));const valid=record&&RoutineBuilder.validateSaved(record);section.querySelector('#routineSavedSummary').textContent=valid?'Saved plan · '+record.profile.days+' days / week · '+record.profile.minutes+' min sessions':'';section.querySelector('#openRoutineStudio').firstChild.textContent=valid?'Review / edit routine ':'Set up my routine ';}catch{}}
const routineForm=dialog.querySelector('#routineForm');routineForm.addEventListener('submit',()=>{if(dialog.querySelector('.routine-message').textContent.startsWith('Your starting routine is ready'))requestAnimationFrame(()=>dialog.querySelector('#routineOutput').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'}));});section.setAttribute('aria-labelledby','routineLaunchHeading');const open=()=>dialog.showModal();section.querySelector('button').onclick=open;dialog.querySelector('.close').onclick=()=>dialog.close();document.querySelectorAll('a[href="#routines"]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();open();}));document.addEventListener('routine:saved',summary);summary();})();
